                                Navigation.navigate(appendParam(backTo, fieldName, format(new Date(`${date} ${time}`), 'yyyy-MM-dd HH:mm:ss.SSS')));
                            }
                        }}
                        defaultValue={fieldValue}
                        shouldValidate={false}
